import {
  Body,
  Controller,
  Delete,
  Get,
  Inject,
  Param,
  ParseIntPipe,
  Patch,
  Post,
  Put,
  Query,
} from '@nestjs/common';
import { ClientProxy } from '@nestjs/microservices';
import {
  AddCartItemDto,
  ApplyCartPromoDto,
  CartLookupDto,
  CartTokenDto,
  ReplaceCartDto,
  UpdateCartItemDto,
} from '../../../libs/dto/orders/cart.dto.js';
import { sendRpc } from '../../../libs/rpc/rpc-client.util.js';
import { Public } from '../auth/decorators/public.decorators.js';

/**
 * Storefront cart. The cart token is generated by the browser and persists in
 * localStorage, so guest carts survive reloads and are linked to the customer
 * once they sign in.
 */
@Public()
@Controller('cart')
export class CartController {
  constructor(
    @Inject('ORDERS_SERVICE')
    private readonly ordersClient: ClientProxy,
  ) {}

  private call<T>(cmd: string, payload: unknown): Promise<T> {
    return sendRpc<T>(this.ordersClient, cmd, payload);
  }

  @Get()
  get(@Query() query: CartLookupDto) {
    return this.call('cart.get', query);
  }

  /** Replace the whole cart (used to push a browser cart to the server). */
  @Put()
  replace(@Body() data: ReplaceCartDto) {
    return this.call('cart.replace', data);
  }

  @Post('items')
  addItem(@Body() data: AddCartItemDto) {
    return this.call('cart.addItem', data);
  }

  /** Absolute quantity; 0 removes the line. */
  @Patch('items/:itemId')
  updateItem(
    @Param('itemId', ParseIntPipe) itemId: number,
    @Body() data: UpdateCartItemDto,
  ) {
    return this.call('cart.updateItem', { ...data, itemId });
  }

  @Delete('items/:itemId')
  removeItem(
    @Param('itemId', ParseIntPipe) itemId: number,
    @Query() query: CartTokenDto,
  ) {
    return this.call('cart.removeItem', {
      cartToken: query.cartToken,
      itemId,
    });
  }

  @Post('promo')
  applyPromo(@Body() data: ApplyCartPromoDto) {
    return this.call('cart.applyPromo', data);
  }

  @Delete('promo')
  removePromo(@Query() query: CartTokenDto) {
    return this.call('cart.removePromo', query);
  }

  @Delete()
  clear(@Query() query: CartTokenDto) {
    return this.call('cart.clear', query);
  }
}
